CREATE TABLE IF NOT EXISTS user (id INT AUTO_INCREMENT PRIMARY KEY, username VARCHAR(50) NOT NULL UNIQUE, password VARCHAR(100) NOT NULL, real_name VARCHAR(50), phone VARCHAR(20), role VARCHAR(20) NOT NULL DEFAULT 'student', is_initialized INT NOT NULL DEFAULT 0) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS building (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(50) NOT NULL UNIQUE, gender VARCHAR(10) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS dormitory (id INT AUTO_INCREMENT PRIMARY KEY, dormitory_number VARCHAR(80) NOT NULL UNIQUE, building VARCHAR(50), room_type VARCHAR(20), capacity INT NOT NULL DEFAULT 4, current_count INT NOT NULL DEFAULT 0, gender VARCHAR(10), remark VARCHAR(200), CHECK(capacity > 0 AND current_count >= 0 AND current_count <= capacity)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS student (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(50) NOT NULL, student_id VARCHAR(20) NOT NULL UNIQUE, grade VARCHAR(10) NOT NULL, class_name VARCHAR(50), gender VARCHAR(10), phone VARCHAR(20) NOT NULL, dormitory_number VARCHAR(80), is_dormitory_leader INT NOT NULL DEFAULT 0, INDEX idx_student_dormitory(dormitory_number)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS repair_request (id INT AUTO_INCREMENT PRIMARY KEY, student_id VARCHAR(20) NOT NULL, student_name VARCHAR(50) NOT NULL, dormitory_number VARCHAR(80) NOT NULL, repair_type VARCHAR(50) NOT NULL, description TEXT, image_path VARCHAR(200), status VARCHAR(20) NOT NULL DEFAULT '待处理', create_time DATETIME(6) DEFAULT CURRENT_TIMESTAMP(6), update_time DATETIME(6) DEFAULT CURRENT_TIMESTAMP(6), INDEX idx_repair_student(student_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
